namespace AquaFlow.Services;

// In-app notifications generated by business events ("the other side" of a water meter request,
// fault report, invoice/payment or support ticket gets told what happened). Scoped - it works on the
// request's own AquaFlowDbContext, which is the whole point: see Stage.
public interface ISystemNotificationService
{
    // Adds one Notification (IsSystem = true, Audience = Direct, CreatedById = actorUserId) plus one
    // UserNotification inbox row per recipient to the CURRENT DbContext WITHOUT saving. The caller's
    // own SaveChanges (e.g. the state machine's TransitionToAsync) persists them together with the
    // business change, so the status change and its notification commit or roll back as one unit.
    // The actor is never notified about their own action (dropped from the recipients) unless
    // notifyActor is set - only for events with no human actor, e.g. a Stripe webhook whose history
    // row is attributed to the paying customer. Nothing is staged when no recipient is left.
    void Stage(SystemNotificationMessage message, IEnumerable<int> recipientUserIds, int actorUserId, bool notifyActor = false);

    // Every active, non-deleted user whose role holds the given (active) permission code - the
    // recipients of events that go "to the staff" (e.g. SupportTickets.Manage for a new ticket).
    Task<List<int>> GetUserIdsWithPermissionAsync(string permissionCode);

    // User.Id behind a CustomerProfile / CollectorProfile id, or null when the profile is missing.
    Task<int?> GetCustomerUserIdAsync(int customerProfileId);
    Task<int?> GetCollectorUserIdAsync(int collectorProfileId);

    // Call AFTER the business operation's save/commit succeeded. Sends the FCM push for every staged
    // notification that was actually persisted (an unsaved one - its save failed - is dropped from the
    // change tracker instead) and clears the staged list. Never throws: push failures are logged and
    // swallowed by NotificationPushDispatcher, so a push problem can't fail or undo the operation.
    Task DispatchPendingPushAsync();
}
